// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC721/ERC721.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "./Quality.sol";

contract ShoeboxNFT is ERC721, Ownable {
    struct Shoebox {
        Quality quality;
        bool isOpened;
    }

    mapping(uint256 => Shoebox) public shoeboxes;
    uint256 private _tokenIds;

    event ShoeboxOpened(uint256 indexed tokenId, Quality quality);
    event ShoeboxMinted(uint256 indexed tokenId, Quality quality, address to);

    constructor() ERC721("HealthStep Shoebox", "HSBS") Ownable() {}

    function mint(
        address to,
        Quality quality
    ) external onlyOwner returns (uint256) {
        _tokenIds++;
        _mint(to, _tokenIds);
        shoeboxes[_tokenIds] = Shoebox({quality: quality, isOpened: false});
        emit ShoeboxMinted(_tokenIds, quality, to);
        return _tokenIds;
    }

    function isOpened(uint256 tokenId) external view returns (bool) {
        require(_exists(tokenId), "Token does not exist");
        return shoeboxes[tokenId].isOpened;
    }

    function getQuality(uint256 tokenId) external view returns (Quality) {
        require(_exists(tokenId), "Token does not exist");
        return shoeboxes[tokenId].quality;
    }

    function markAsOpened(uint256 tokenId) external onlyOwner {
        require(_exists(tokenId), "Token does not exist");
        require(!shoeboxes[tokenId].isOpened, "Already opened");
        shoeboxes[tokenId].isOpened = true;
        emit ShoeboxOpened(tokenId, shoeboxes[tokenId].quality);
    }
}

