// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC721/ERC721.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "./Quality.sol";

contract SneakerNFT is ERC721, Ownable {
    bytes32 public constant DURABILITY_MANAGER_ROLE =
        keccak256("DURABILITY_MANAGER_ROLE");
    mapping(address => bool) public durabilityManagers;

    struct Sneaker {
        Quality quality;
        uint256 mintCount;
        uint256 lastMintTime;
        uint256 durability;
    }

    mapping(uint256 => Sneaker) public sneakers;
    uint256 private _tokenIds;
    uint256 public constant MINT_COOLDOWN = 2 days;
    uint256 public constant MAX_MINT_COUNT = 7;
    uint256 public constant MAX_DURABILITY = 100;

    constructor() ERC721("HealthStep Sneaker", "HSNS") Ownable() {}

    function mint(
        address to,
        Quality quality
    ) external onlyOwner returns (uint256) {
        _tokenIds++;
        _mint(to, _tokenIds);
        sneakers[_tokenIds] = Sneaker({
            quality: quality,
            mintCount: 0,
            lastMintTime: 0,
            durability: MAX_DURABILITY
        });
        return _tokenIds;
    }

    function canMint(uint256 tokenId) public view returns (bool) {
        Sneaker memory sneaker = sneakers[tokenId];
        return
            sneaker.mintCount < MAX_MINT_COUNT &&
            block.timestamp >= sneaker.lastMintTime + MINT_COOLDOWN &&
            sneaker.durability == MAX_DURABILITY;
    }

    function updateAfterMint(uint256 tokenId) external onlyOwner {
        require(_exists(tokenId), "Token does not exist");
        Sneaker storage sneaker = sneakers[tokenId];
        require(sneaker.mintCount < MAX_MINT_COUNT, "Max mints reached");

        sneaker.mintCount++;
        sneaker.lastMintTime = block.timestamp;
        require(sneaker.mintCount <= MAX_MINT_COUNT, "Exceeds max mint count");
    }

    function setDurabilityManager(
        address manager,
        bool status
    ) external onlyOwner {
        durabilityManagers[manager] = status;
    }

    function updateDurability(uint256 tokenId, uint256 newDurability) external {
        require(durabilityManagers[msg.sender], "Not authorized");
        require(_exists(tokenId), "Token does not exist");
        require(newDurability <= MAX_DURABILITY, "Exceeds max durability");
        sneakers[tokenId].durability = newDurability;
    }
}

