// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

contract HealthStepCoinEarn is ERC20, Ownable {
    uint256 public constant MAX_SUPPLY = 500000000 * 10 ** 18; // 500 million tokens
    uint256 public earnedAmount;
    uint256 public remainingSupply;
    uint256 public currentEarnRate;

    constructor() ERC20("Health Step Coin Earn", "HSCE") Ownable() {
        earnedAmount = 0;
        remainingSupply = MAX_SUPPLY;
        currentEarnRate = 1 * 10 ** 18; // Start with 1 token earn rate
        _mint(msg.sender, MAX_SUPPLY);
    }

    function _mint(address account, uint256 amount) internal override(ERC20) {
        require(amount > 0, "Amount must be greater than 0");
        require(remainingSupply > 0, "No remaining supply");

        uint256 halfRemaining = remainingSupply / 2;
        uint256 adjustedAmount = (amount * currentEarnRate) / (1 * 10 ** 18);

        if (earnedAmount + adjustedAmount >= halfRemaining) {
            // Halve the earn rate when we reach half of remaining supply
            currentEarnRate = currentEarnRate / 2;
            adjustedAmount = (amount * currentEarnRate) / (1 * 10 ** 18);
        }

        if (adjustedAmount > remainingSupply) {
            adjustedAmount = remainingSupply;
        }

        remainingSupply -= adjustedAmount;
        earnedAmount += adjustedAmount;
        super._mint(account, adjustedAmount);
    }

    function getCurrentEarnRate() public view returns (uint256) {
        return currentEarnRate;
    }
}

